(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-333":{scenario:{legacy:"C"},learning:{summary:{vi:"Chuyên viên chăm sóc khách hàng và xử lý khiếu nại đa kênh tiếp nhận, giải quyết yêu cầu của khách qua tổng đài, chat, email, mạng xã hội, sàn thương mại điện tử và cửa hàng; ghi nhận đầy đủ trên hệ thống quản lý yêu cầu, phân loại mức ưu tiên, xử lý theo chính sách đổi trả, bảo hành, hoàn tiền và chuyển cấp đúng thời hạn cam kết (SLA). Nghề đòi hỏi kỹ năng lắng nghe, kiềm chế cảm xúc, hiểu sản phẩm, chính sách, pháp luật bảo vệ người tiêu dùng và giữ bí mật dữ liệu cá nhân của khách hàng.",en:"An omnichannel customer service specialist receives and resolves customer requests across the hotline, chat, email, social media, marketplaces and stores; logs every case in the ticketing system, sets priority, applies return, warranty and refund policies and escalates within the committed service level (SLA). The role requires active listening, emotional self-control, product and policy knowledge, consumer protection law and strict protection of customers' personal data."},responsibilities:{vi:["Tiếp nhận yêu cầu, khiếu nại trên mọi kênh và tạo phiếu với đầy đủ thông tin, bằng chứng.","Phân loại, xác định mức ưu tiên và xử lý theo chính sách đổi trả, bảo hành, hoàn tiền.","Chuyển cấp vụ việc vượt thẩm quyền cho bộ phận liên quan và theo dõi đến khi đóng phiếu.","Phản hồi khách đúng SLA và giữ thông tin nhất quán giữa các kênh.","Ghi nhận nguyên nhân gốc của khiếu nại và đề xuất cải tiến sản phẩm, quy trình."],en:["Receive requests and complaints on every channel and open tickets with full details and evidence.","Classify, prioritize and resolve cases under return, warranty and refund policies.","Escalate cases beyond your authority to the right team and follow them until closure.","Reply within the SLA and keep information consistent across channels.","Record complaint root causes and propose product and process improvements."]},competencies:[{name:{vi:"Lắng nghe & thấu cảm",en:"Active listening & empathy"},desc:{vi:"Nghe hết vấn đề, xác nhận lại cảm xúc và nhu cầu của khách trước khi đưa giải pháp.",en:"Hear the whole issue and acknowledge the customer's feelings and needs before offering a fix."}},{name:{vi:"Giải quyết vấn đề",en:"Problem solving"},desc:{vi:"Xác minh dữ kiện, tìm nguyên nhân và chọn phương án nằm trong chính sách.",en:"Verify facts, find causes and choose a solution within policy."}},{name:{vi:"Am hiểu chính sách & sản phẩm",en:"Policy & product knowledge"},desc:{vi:"Nắm điều kiện đổi trả, bảo hành, hoàn tiền và cách tra cứu cơ sở tri thức nhanh.",en:"Know return, warranty and refund conditions and search the knowledge base fast."}},{name:{vi:"Giao tiếp đa kênh",en:"Omnichannel communication"},desc:{vi:"Viết chat ngắn gọn, email chuẩn mực và phản hồi công khai trên mạng xã hội an toàn.",en:"Write concise chats, proper emails and safe public replies on social media."}},{name:{vi:"Bảo mật & chính trực",en:"Privacy & integrity"},desc:{vi:"Xác minh danh tính trước khi cung cấp thông tin, không hứa vượt thẩm quyền, không che giấu phản hồi tiêu cực.",en:"Verify identity before sharing data, never promise beyond authority and never hide negative feedback."}}],knowledge:{vi:["Luật Bảo vệ quyền lợi người tiêu dùng 2023: quyền khiếu nại của người tiêu dùng và nghĩa vụ tiếp nhận, giải quyết của tổ chức kinh doanh.","ISO 10002 hướng dẫn xử lý khiếu nại trong tổ chức và ISO 10004 về theo dõi, đo lường sự hài lòng của khách hàng.","ISO 18295 về yêu cầu đối với trung tâm liên lạc khách hàng.","Quy định về bảo vệ dữ liệu cá nhân: xác minh chủ thể, chỉ cung cấp thông tin đúng người, thông báo khi ghi âm cuộc gọi.","Chỉ số dịch vụ FCR, CSAT, NPS, AHT và cam kết SLA phản hồi, giải quyết."],en:["Consumer Protection Law 2023: consumers' right to complain and businesses' duty to receive and resolve complaints.","ISO 10002 guidelines for complaints handling and ISO 10004 for monitoring and measuring customer satisfaction.","ISO 18295 requirements for customer contact centres.","Personal data protection rules: verify the data subject, share data only with the right person, announce call recording.","Service metrics FCR, CSAT, NPS and AHT and response and resolution SLAs."]},tools:["Hệ thống quản lý yêu cầu (ticketing)","Tổng đài đa kênh (contact center)","Hệ thống CRM","Cơ sở tri thức nội bộ","Công cụ khảo sát hài lòng"],kpis:{vi:["Tỷ lệ giải quyết ngay lần liên hệ đầu tiên (FCR).","Điểm hài lòng sau tương tác (CSAT).","Tỷ lệ phiếu được phản hồi và giải quyết đúng SLA.","Tỷ lệ phiếu bị mở lại hoặc khiếu nại leo thang ra bên ngoài."],en:["First contact resolution rate (FCR).","Post-interaction satisfaction score (CSAT).","Share of tickets answered and resolved within SLA.","Reopened tickets or complaints escalated outside the company."]},day:[{time:"08:00",vi:"Đọc bàn giao ca, rà soát phiếu tồn sắp quá SLA và cảnh báo sự cố sản phẩm.",en:"Read the shift handover and review tickets near SLA breach and product incident alerts."},{time:"09:00",vi:"Trực tổng đài và chat giờ cao điểm, xử lý yêu cầu đổi trả, giao hàng.",en:"Handle peak-hour calls and chats on returns and deliveries."},{time:"11:30",vi:"Trả lời email, tin nhắn sàn thương mại điện tử và bình luận mạng xã hội.",en:"Answer emails, marketplace messages and social media comments."},{time:"14:00",vi:"Họp với kho, kỹ thuật về một vụ khiếu nại bảo hành phức tạp.",en:"Meet warehouse and technical teams on a complex warranty complaint."},{time:"16:30",vi:"Ghi nhận nguyên nhân gốc, cập nhật cơ sở tri thức và báo cáo cuối ca.",en:"Record root causes, update the knowledge base and file the end-of-shift report."}],mistakes:{vi:["Đóng phiếu khi khách chưa xác nhận vấn đề đã được giải quyết.","Cung cấp thông tin đơn hàng, tài khoản khi chưa xác minh đúng chủ thể dữ liệu.","Hứa bồi hoàn vượt thẩm quyền hoặc trả lời mỗi kênh một kiểu, làm khiếu nại leo thang."],en:["Closing a ticket before the customer confirms the issue is solved.","Sharing order or account data before verifying the data subject.","Promising compensation beyond authority or answering differently on each channel, escalating the complaint."]},career:[{vi:"Nhân viên chăm sóc khách hàng",en:"Customer service agent"},{vi:"Chuyên viên xử lý khiếu nại đa kênh",en:"Omnichannel complaints specialist"},{vi:"Trưởng nhóm / giám sát dịch vụ khách hàng",en:"Customer service team lead or supervisor"},{vi:"Quản lý trải nghiệm khách hàng",en:"Customer experience manager"}],glossary:[{term:"FCR",vi:"Tỷ lệ yêu cầu được giải quyết ngay trong lần liên hệ đầu tiên.",en:"Share of requests resolved in the first contact."},{term:"CSAT",vi:"Điểm hài lòng của khách sau một lần tương tác hoặc giải quyết khiếu nại.",en:"Customer satisfaction score after an interaction or complaint resolution."},{term:"NPS",vi:"Chỉ số sẵn lòng giới thiệu: tỷ lệ khách chấm 9-10 trừ tỷ lệ khách chấm 0-6.",en:"Net Promoter Score: share of 9-10 scores minus share of 0-6 scores."},{term:"SLA",vi:"Cam kết mức độ dịch vụ: thời hạn phản hồi và giải quyết cho từng mức ưu tiên.",en:"Service level agreement: response and resolution times per priority."},{term:"Escalation",vi:"Chuyển cấp: chuyển vụ việc vượt thẩm quyền lên cấp hoặc bộ phận có quyền quyết định.",en:"Passing a case beyond your authority to the level or team that can decide."}],quiz:[{q:{vi:"Khảo sát 200 khách: 110 chấm 9-10, 50 chấm 7-8, 40 chấm 0-6. NPS là bao nhiêu?",en:"Of 200 surveyed customers, 110 scored 9-10, 50 scored 7-8 and 40 scored 0-6. What is the NPS?"},options:{vi:["55","15","35","45"],en:["55","15","35","45"]},answer:2,explain:{vi:"Tỷ lệ khách ủng hộ 55% trừ tỷ lệ khách phản đối 20% = 35; nhóm 7-8 là trung lập, không tính.",en:"55% promoters minus 20% detractors = 35; the 7-8 group is passive and not counted."}},{q:{vi:"Chỉ số FCR đo điều gì?",en:"What does FCR measure?"},options:{vi:["Tỷ lệ vấn đề được giải quyết ngay lần liên hệ đầu tiên","Thời gian xử lý trung bình mỗi cuộc gọi","Số cuộc gọi nhỡ trong ca","Điểm hài lòng sau khảo sát"],en:["Share of issues resolved in the first contact","Average handling time per call","Missed calls per shift","Post-survey satisfaction score"]},answer:0,explain:{vi:"FCR cao giảm số lần khách phải liên hệ lại và thường đi cùng mức hài lòng cao hơn.",en:"High FCR reduces repeat contacts and usually goes with higher satisfaction."}},{q:{vi:"Người gọi tự xưng là chồng của chủ tài khoản, yêu cầu đọc địa chỉ và lịch sử đơn hàng của vợ. Bạn làm gì?",en:"A caller says he is the account holder's husband and asks for her address and order history. What do you do?"},options:{vi:["Đọc vì là người nhà","Chỉ đọc địa chỉ giao hàng","Gửi thông tin qua tin nhắn cho người gọi","Từ chối khi chưa xác minh đúng chủ tài khoản và hướng dẫn chủ tài khoản liên hệ"],en:["Share it because he is family","Share only the delivery address","Text the data to the caller","Decline until the account holder is verified and guide her to contact you"]},answer:3,explain:{vi:"Dữ liệu cá nhân chỉ được cung cấp cho đúng chủ thể hoặc người được ủy quyền hợp lệ sau khi xác minh.",en:"Personal data may only go to the verified data subject or a validly authorized person."}},{q:{vi:"Khách đòi bồi thường vượt chính sách và dọa đăng lên mạng xã hội. Phương án đúng là gì?",en:"A customer demands compensation beyond policy and threatens to post on social media. What is right?"},options:{vi:["Đồng ý ngay để tránh khủng hoảng","Lắng nghe, ghi nhận, giải thích chính sách, chuyển cấp có thẩm quyền xét ngoại lệ và hẹn thời hạn phản hồi","Chặn khách trên mọi kênh","Xóa bình luận tiêu cực của khách"],en:["Agree at once to avoid a crisis","Listen, log it, explain the policy, escalate for an exception review and commit a reply time","Block the customer on all channels","Delete the customer's negative comments"]},answer:1,explain:{vi:"Xử lý bình tĩnh, minh bạch và đúng thẩm quyền giữ được niềm tin; hứa vượt chính sách hoặc che giấu đều làm vụ việc tệ hơn.",en:"Calm, transparent handling within authority keeps trust; over-promising or hiding feedback makes it worse."}}],tools_en:["Ticketing system","Omnichannel contact center","CRM system","Internal knowledge base","Customer satisfaction survey tools"]}}})})(window.KKR);
